}

function readErrorDetail(jqXHR) {
  if (jqXHR.responseJSON && (jqXHR.responseJSON.detail || jqXHR.responseJSON.error)) {
    return jqXHR.responseJSON.detail || jqXHR.responseJSON.error;
  }
  var text = jqXHR.responseText || '';
  if (text && text.charAt(0) === '{') {
    try {
      var parsed = JSON.parse(text);
      if (parsed.detail) return parsed.detail;
      if (parsed.error)  return parsed.error;
    } catch (e) { /* fall through */ }
  }
  return jqXHR.statusText || ('HTTP ' + jqXHR.status);
}

function showError(msg) {
  $('#error-msg').html(escapeHtml(msg)).show();
  $('#result-area').hide();
}

function parseIds() {
  var raw = $('#id-input').val() || '';
  var parts = raw.split(/[\s,;]+/).map(function(s) { return s.trim(); }).filter(Boolean);
  return parts;
}

